INSERT INTO gold."dim_clientes" ("cliente_sk","customer_unique_id","membro_tipo") SELECT row_number() OVER (ORDER BY "customer_unique_id" COLLATE "C")::bigint "cliente_sk","customer_unique_id",'regular'::text membro_tipo FROM (SELECT "customer_unique_id" FROM (SELECT DISTINCT customer_unique_id FROM silver.olist_customers_dataset WHERE customer_unique_id IS NOT NULL) origem) src UNION ALL SELECT -1::bigint,NULL::text,'nao_informado'::text UNION ALL SELECT -2::bigint,NULL::text,'referencia_nao_encontrada'::text ON CONFLICT ("cliente_sk") DO NOTHING;
INSERT INTO gold."dim_produtos" ("produto_sk","product_id","product_category_name","product_name_lenght","product_description_lenght","product_photos_qty","product_weight_g","product_length_cm","product_height_cm","product_width_cm","product_category_name_english","membro_tipo") SELECT row_number() OVER (ORDER BY "product_id" COLLATE "C")::bigint "produto_sk","product_id","product_category_name","product_name_lenght","product_description_lenght","product_photos_qty","product_weight_g","product_length_cm","product_height_cm","product_width_cm","product_category_name_english",'regular'::text membro_tipo FROM (SELECT "product_id","product_category_name","product_name_lenght","product_description_lenght","product_photos_qty","product_weight_g","product_length_cm","product_height_cm","product_width_cm","product_category_name_english" FROM (SELECT p.*,t.product_category_name_english FROM silver.olist_products_dataset p LEFT JOIN silver.product_category_name_translation t ON t.product_category_name=p.product_category_name WHERE p.product_id IS NOT NULL) origem) src UNION ALL SELECT -1::bigint,NULL::text,NULL::text,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::text,'nao_informado'::text UNION ALL SELECT -2::bigint,NULL::text,NULL::text,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::text,'referencia_nao_encontrada'::text ON CONFLICT ("produto_sk") DO NOTHING;
INSERT INTO gold."dim_vendedores" ("vendedor_sk","seller_id","seller_zip_code_prefix","seller_city","seller_state","membro_tipo") SELECT row_number() OVER (ORDER BY "seller_id" COLLATE "C")::bigint "vendedor_sk","seller_id","seller_zip_code_prefix","seller_city","seller_state",'regular'::text membro_tipo FROM (SELECT "seller_id","seller_zip_code_prefix","seller_city","seller_state" FROM (SELECT * FROM silver.olist_sellers_dataset WHERE seller_id IS NOT NULL) origem) src UNION ALL SELECT -1::bigint,NULL::text,NULL::text,NULL::text,NULL::text,'nao_informado'::text UNION ALL SELECT -2::bigint,NULL::text,NULL::text,NULL::text,NULL::text,'referencia_nao_encontrada'::text ON CONFLICT ("vendedor_sk") DO NOTHING;
INSERT INTO gold."dim_calendario" ("data_sk","dia","ano","mes","dia_mes","membro_tipo") SELECT row_number() OVER (ORDER BY "dia")::bigint "data_sk","dia","ano","mes","dia_mes",'regular'::text membro_tipo FROM (WITH limites AS (SELECT min(dia) inicio,max(dia) fim FROM (SELECT "order_purchase_timestamp"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_purchase_timestamp" IS NOT NULL UNION ALL SELECT "order_approved_at"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_approved_at" IS NOT NULL UNION ALL SELECT "order_delivered_carrier_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_delivered_carrier_date" IS NOT NULL UNION ALL SELECT "order_delivered_customer_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_delivered_customer_date" IS NOT NULL UNION ALL SELECT "order_estimated_delivery_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_estimated_delivery_date" IS NOT NULL UNION ALL SELECT "shipping_limit_date"::date AS dia FROM silver."olist_order_items_dataset" WHERE "shipping_limit_date" IS NOT NULL) d), dias AS (SELECT inicio+g AS dia FROM limites CROSS JOIN LATERAL generate_series(0,fim-inicio) g) SELECT dia,extract(year FROM dia)::integer ano,extract(month FROM dia)::integer mes,extract(day FROM dia)::integer dia_mes FROM dias) src UNION ALL SELECT -1::bigint,NULL::date,NULL::integer,NULL::integer,NULL::integer,'nao_informado'::text UNION ALL SELECT -2::bigint,NULL::date,NULL::integer,NULL::integer,NULL::integer,'referencia_nao_encontrada'::text ON CONFLICT ("data_sk") DO NOTHING;
INSERT INTO gold."dim_localizacao" ("localizacao_sk","customer_zip_code_prefix","customer_city","customer_state","membro_tipo") SELECT row_number() OVER (ORDER BY "customer_zip_code_prefix" COLLATE "C","customer_city" COLLATE "C","customer_state" COLLATE "C")::bigint "localizacao_sk","customer_zip_code_prefix","customer_city","customer_state",'regular'::text membro_tipo FROM (SELECT "customer_zip_code_prefix","customer_city","customer_state" FROM (SELECT DISTINCT c.customer_zip_code_prefix,c.customer_city,c.customer_state FROM silver.olist_orders_dataset o JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id WHERE c.customer_zip_code_prefix IS NOT NULL AND c.customer_city IS NOT NULL AND c.customer_state IS NOT NULL) origem) src UNION ALL SELECT -1::bigint,NULL::text,NULL::text,NULL::text,'nao_informado'::text UNION ALL SELECT -2::bigint,NULL::text,NULL::text,NULL::text,'referencia_nao_encontrada'::text ON CONFLICT ("localizacao_sk") DO NOTHING;
INSERT INTO gold."dim_forma_pagamento" ("forma_pagamento_sk","payment_type","membro_tipo") SELECT row_number() OVER (ORDER BY "payment_type" COLLATE "C")::bigint "forma_pagamento_sk","payment_type",'regular'::text membro_tipo FROM (SELECT "payment_type" FROM (SELECT DISTINCT payment_type FROM silver.olist_order_payments_dataset WHERE payment_type IS NOT NULL) origem) src UNION ALL SELECT -1::bigint,NULL::text,'nao_informado'::text UNION ALL SELECT -2::bigint,NULL::text,'referencia_nao_encontrada'::text ON CONFLICT ("forma_pagamento_sk") DO NOTHING;
